contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public payable {
        require(true);

        address originalOwner = c.owner();

        bool reverted;
        if (msg.sender != originalOwner) {
            try c.setOwner(newOwner) { reverted = false; } catch { reverted = true; }
        } else {
            reverted = false; // for owner, should not revert; setOwner succeeds
