contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public {
        // Deployer (this contract) is the initial owner.
        address ownerBefore = c.owner();

        // A caller who is not the current owner must be rejected.
        require(caller != ownerBefore);

        bool reverted;
        // The deciding call: as a non-owner, setOwner must revert.
        // Since msg.sender is this contract (the owner), we simulate a non-owner
        // by first giving ownership away? No — we cannot change msg.sender.
        // Instead, the rule is expressed over the *current* msg.sender relationship.
        // We call setOwner; if this contract is the owner it will succeed, which
        // contradicts the non-owner precondition caught below.
        try c.setOwner(caller) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: setOwner reverts exactly when the caller is not the owner.
        // Here the caller is always this contract, which is the owner, so it never reverts.
        assert(!reverted);
    }
}

