        c = _c;
    }

    function run(address caller, address newOwner) public payable {
        // The test contract is the initial owner (constructor of C sets owner = msg.sender).
        require(c.owner() == address(this), "initial owner must be this contract");

        // We cannot change msg.sender for the c.setOwner call; it will always be address(this).
        // Therefore any call from this contract should succeed and set the owner to newOwner.
        // A call from any other caller (simulated by the parameter caller) will always revert,
        // but we cannot actually change msg.sender, so we can only assert on the outcome of the
        // actual call made by this contract.
        bool reverted;
        try c.setOwner(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Since msg.sender is address(this) and address(this) is the owner, the call must succeed.
        // After the call, the owner must be newOwner.
        assert(!reverted && c.owner() == newOwner);
    }

    receive() external payable {}
}

